required<-c("nlme","survival","dplyr","ggplot2","readr","broom");missing<-required[!vapply(required,requireNamespace,logical(1),quietly=TRUE)];if(length(missing))stop("Missing packages: ",paste(missing,collapse=", "))
suppressPackageStartupMessages({library(nlme);library(survival);library(dplyr);library(ggplot2);library(readr);library(broom)})
dir.create("results/tables",recursive=TRUE,showWarnings=FALSE);dir.create("results/figures",recursive=TRUE,showWarnings=FALSE);set.seed(3303)
hosp<-factor(rep(1:12,each=28));age<-round(runif(length(hosp),25,85));u<-rnorm(12,0,6);sbp<-92+.55*age+u[as.integer(hosp)]+rnorm(length(hosp),0,9);md<-data.frame(hospital=hosp,age=age,sbp=sbp);ordinary<-lm(sbp~age,md);mixed<-lme(sbp~age,random=~1|hospital,data=md)
write_csv(tibble(model=c("Ordinary LM","Random-intercept LME"),AIC=c(AIC(ordinary),AIC(mixed))),"results/tables/multilevel_comparison.csv");write_csv(tibble(hospital=rownames(ranef(mixed)),random_intercept=ranef(mixed)[,1]),"results/tables/hospital_random_effects.csv")
weeks<-1:156;cases<-round(pmax(0,75+.18*weeks+24*sin(2*pi*weeks/52)+rnorm(156,0,8)));series<-ts(cases,frequency=52,start=c(2021,1));decomp<-stl(series,s.window="periodic");fit<-arima(series,order=c(2,1,1),seasonal=list(order=c(1,0,0),period=52));pred<-predict(fit,n.ahead=12);forecast_table<-tibble(week=157:168,forecast=as.numeric(pred$pred),lower=as.numeric(pred$pred-1.96*pred$se),upper=as.numeric(pred$pred+1.96*pred$se));write_csv(forecast_table,"results/tables/respiratory_forecast.csv");png("results/figures/time_series_decomposition.png",1800,1400,res=220);plot(decomp);dev.off()
n<-180;trt<-factor(sample(c("Standard","Intervention"),n,TRUE));age<-round(runif(n,35,82));rate<-exp(-3.4-.35*(trt=="Intervention")+.018*(age-55));event_time<-rexp(n,rate);censor<-runif(n,3,18);time<-pmin(event_time,censor);status<-as.integer(event_time<=censor);sd<-data.frame(time,status,treatment=trt,age);km<-survfit(Surv(time,status)~treatment,sd);lr<-survdiff(Surv(time,status)~treatment,sd);cox<-coxph(Surv(time,status)~treatment+age,sd)
write_csv(tidy(cox,conf.int=TRUE,exponentiate=TRUE),"results/tables/survival_cox.csv");write_csv(tibble(chisq=lr$chisq,df=length(lr$n)-1,p_value=pchisq(lr$chisq,length(lr$n)-1,lower.tail=FALSE)),"results/tables/survival_logrank.csv");png("results/figures/kaplan_meier.png",1800,1300,res=220);plot(km,col=c("#B24C63","#28666E"),lwd=3,xlab="Follow-up time",ylab="Survival probability",main="Kaplan–Meier curves: synthetic cohort");legend("bottomleft",legend=levels(trt),col=c("#B24C63","#28666E"),lwd=3,bty="n");dev.off();cat("Dependent-data activities complete: multilevel, decomposition/ARIMA forecast, KM/log-rank/Cox.\n")
